module elastic_dot4_core (
    input wire clk,
    input wire rst,
    input wire [7:0] a0,
    input wire [7:0] b0,
    input wire [7:0] a1,
    input wire [7:0] b1,
    input wire [7:0] a2,
    input wire [7:0] b2,
    input wire [7:0] a3,
    input wire [7:0] b3,
    input wire in_valid,
    output wire in_ready,
    output wire [17:0] out_data,
    output wire out_valid,
    input wire out_ready
);

    reg [16:0] partial_sum_01;
    reg [16:0] partial_sum_23;
    reg valid_stage1;
    reg [17:0] result_stage2;
    reg valid_stage2;

    (* use_dsp = "yes" *) wire [15:0] product_0 = a0 * b0;
    (* use_dsp = "yes" *) wire [15:0] product_1 = a1 * b1;
    (* use_dsp = "yes" *) wire [15:0] product_2 = a2 * b2;
    (* use_dsp = "yes" *) wire [15:0] product_3 = a3 * b3;

    wire [16:0] input_sum_01 = {1'b0, product_0} + {1'b0, product_1};
    wire [16:0] input_sum_23 = {1'b0, product_2} + {1'b0, product_3};
    wire [17:0] stage1_sum = {1'b0, partial_sum_01} + {1'b0, partial_sum_23};

    wire stage2_ready = !valid_stage2 || out_ready;

    assign in_ready = !valid_stage1 || stage2_ready;
    assign out_valid = valid_stage2;
    assign out_data = result_stage2;

    always @(posedge clk) begin
        if (rst) begin
            valid_stage1 <= 1'b0;
            valid_stage2 <= 1'b0;
        end else begin
            if (stage2_ready) begin
                valid_stage2 <= valid_stage1;
                if (valid_stage1)
                    result_stage2 <= stage1_sum;
            end

            if (in_ready) begin
                valid_stage1 <= in_valid;
                if (in_valid) begin
                    partial_sum_01 <= input_sum_01;
                    partial_sum_23 <= input_sum_23;
                end
            end
        end
    end

endmodule

